import zipfile
import re
import xml.etree.ElementTree as ET

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}

z = zipfile.ZipFile('budget.xlsx')

# shared strings
shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    root = ET.fromstring(z.read('xl/sharedStrings.xml'))
    for si in root.findall('m:si', NS):
        shared.append(''.join(t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')))

# find sheet targets
wbroot = ET.fromstring(z.read('xl/workbook.xml'))
rels = ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
relmap = {rel.get('Id'): rel.get('Target') for rel in rels}
sheets = [(sh.get('name'), sh.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id')) for sh in wbroot.find('m:sheets', NS)]

def col_idx(letters):
    idx = 0
    for ch in letters:
        idx = idx * 26 + (ord(ch) - 64)
    return idx

for name, rid in sheets:
    target = relmap.get(rid, '')
    if target.startswith('/'):
        target = target.lstrip('/')
    elif not target.startswith('xl/'):
        target = 'xl/' + target
    print(f"=== Sheet: {name} ({target}) ===")
    root = ET.fromstring(z.read(target))
    sd = root.find('m:sheetData', NS)
    cells = {}
    for row in sd.findall('m:row', NS):
        for c in row.findall('m:c', NS):
            ref = c.get('r')
            m = re.match(r'([A-Z]+)(\d+)', ref)
            col, r = col_idx(m.group(1)), int(m.group(2))
            t = c.get('t')
            v = c.find('m:v', NS)
            val = v.text if v is not None else None
            if t == 's' and val is not None:
                val = shared[int(val)]
            elif t == 'b' and val is not None:
                val = val == '1'
            elif t == 'inlineStr':
                is_el = c.find('m:is', NS)
                val = ''.join(tt.text or '' for tt in is_el.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')) if is_el is not None else None
            elif val is not None:
                try:
                    val = float(val)
                except ValueError:
                    pass
            cells[(r, col)] = val

    # print all cells
    for (r, col), val in sorted(cells.items()):
        print(f"  row {r}, col {col}: {val!r}")

    # totals: expenses rows 11-22 (col A category, col C amount), income rows 4-7 (col B)
    per_cat = {}
    total = 0.0
    for r in range(11, 23):
        cat = cells.get((r, 1))
        amt = cells.get((r, 3))
        if amt is None:
            continue
        amt = float(amt)
        per_cat[cat] = per_cat.get(cat, 0.0) + amt
        total += amt
    print("\nPer-category totals:")
    for cat, amt in sorted(per_cat.items(), key=lambda kv: str(kv[0])):
        print(f"  {cat}: {amt:,.2f}")
    print(f"TOTAL EXPENSES: {total:,.2f}")

    income = sum(float(cells.get((r, 2), 0) or 0) for r in range(4, 8))
    print(f"Total income (rows 4-7 col B): {income:,.2f}")
    print(f"Implied balance (income - expenses): {income - total:,.2f}")

